pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: from address (actor), v (value), decimals, and an array length seed
    function testFuzz_property(address from, uint256 v, uint8 decimals, uint8 tosLenSeed) public {
        // keep _tos length in a reasonable but wide range: 1..6 (must be >0 per require)
        uint256 tosLen = 1 + (tosLenSeed % 6);
        address[] memory tos = new address[](tosLen);
        // deploy a benign callee that always returns true for transferFrom selector
        CalleeAccepting callee = new CalleeAccepting();
        for (uint i = 0; i < tosLen; i++) tos[i] = address(uint160(uint(keccak256(abi.encodePacked(from, v, decimals, i)))));

        // call transfer and capture whether it completed (did not revert) and its return value
        bool ok;
        bool ret;
        try c.transfer(from, address(callee), tos, v, uint256(decimals)) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // General rule: for any admissible input where the callee accepts the low-level calls,
        // the reference implementation returns true (and thus call completes). We assert that
        // the call succeeded and returned true. The mutant that always returns false will
        // cause this assertion to fail for some inputs (those where call completes successfully).
        assertTrue(ok && ret);
    }
}

// Minimal adversarial helper: a callee that accepts the low-level call with selector
contract CalleeAccepting {
    // emulate an ERC20-like transferFrom signature handler; respond with no revert and any data
    fallback() external payable returns (bytes memory) {
        // simply return true-encoded (though original uses just call success, not returned data)
        return abi.encode(true);
    }
}

