pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: from (address), tosLength (uint8), v (uint256), decimals (uint8)
    function testFuzz_property(address from, uint8 tosLength, uint256 v, uint8 decimals, address callee) public {
        // admissible domain: tos array must be non-empty per function's require
        vm.assume(tosLength > 0);
        // restrict decimals to reasonable range to avoid overflow in v * 10 ** decimals
        uint8 d = decimals % 19; // 10**19 fits within uint256 for typical v

        // Deploy a helper callee that always accepts the low-level call and returns true-like data
        // If the fuzzed callee is a contract address with code, we still want to route through our helper
        AcceptingC acceptor = new AcceptingC();
        address caddress = address(acceptor);

        // construct _tos array of unique addresses (just populate with distinct addresses derived from keccak)
        address[] memory _tos = new address[](tosLength);
        for (uint i = 0; i < tosLength; i++) {
            // synthesize addresses deterministically from inputs
            _tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, callee, i)))));
        }

        // Call transfer and observe its returned boolean via try/catch to capture revert vs success
        bool ok;
        try c.transfer(from, caddress, _tos, v, uint(d)) returns (bool ret) {
            ok = ret; // the reference contract should return true for successful low-level calls
        } catch {
            ok = false; // if it reverts, mark as false (but for our setup it shouldn't)
        }

        // The general rule: for any non-empty _tos and a callee that accepts the low-level calls, c.transfer(...) returns true.
        // Here acceptor accepts, so assertTrue over c's returned success (ok) — single assertion
        assertTrue(ok);
    }
}

// Minimal helper that accepts the low-level call made with selector transferFrom(address,address,uint256)
contract AcceptingC {
    // Accept any call and return true-encoded data to simulate successful ERC20 transferFrom
    fallback() external payable returns (bytes memory) {
        // return abi.encode(true) so low-level call appears successful with true return data
        return abi.encode(true);
    }
}
